<?php use Hls\Http\View as V; ?><?php if($access->can('inventory.opname.create')): ?><section class="panel"><form method="post" class="form-grid"><?= $this->csrf() ?><label>Nomor opname<input name="opname_ref" required></label><label>Tanggal<input type="date" name="opname_date" value="<?= date('Y-m-d') ?>" required></label><label>Cabang<select name="branch_id" required><?php foreach($branches as $b): if($access->branch((int)$b['id'])): ?><option value="<?= (int)$b['id'] ?>"><?= V::escape($b['code']) ?></option><?php endif; endforeach ?></select></label><label>Gudang<select name="warehouse_id" required><?php foreach($warehouses as $w): if($access->branch((int)$w['branch_id'])): ?><option value="<?= (int)$w['id'] ?>"><?= V::escape($w['code']) ?></option><?php endif; endforeach ?></select></label><label>Barang<select name="item_id[]" required><?php foreach($items as $i): ?><option value="<?= (int)$i['id'] ?>"><?= V::escape($i['code'].' - '.$i['name']) ?></option><?php endforeach ?></select></label><label>Stok fisik<input name="physical_qty[]" type="number" min="0" step="0.001" required></label><button class="button button-primary">Simpan Draft</button></form></section><?php endif ?><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Nomor</th><th>Tanggal</th><th>Cabang</th><th>Gudang</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= V::escape($r['opname_ref']) ?></td><td><?= V::escape($r['opname_date']) ?></td><td><?= V::escape($r['branch_code']) ?></td><td><?= V::escape($r['warehouse_code']) ?></td><td><?= V::escape($r['status']) ?></td><td><a href="<?= $this->url('/inventory/stock-opname-detail?id='.(int)$r['id']) ?>">Detail</a></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="6" class="empty-state">Belum ada stock opname.</td></tr><?php endif ?></tbody></table></div></section>
